document.querySelectorAll('[data-screen]').forEach((button,index,buttons)=>{button.addEventListener('click',()=>{buttons.forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-selected',String(b===button))});const image=document.querySelector('#feature-screen');image.src='screens/'+button.dataset.screen+'.png';image.alt=button.querySelector('h3').textContent;document.querySelector('#screen').setAttribute('aria-labelledby',button.id)});button.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const next=buttons[(index+(e.key==='ArrowRight'?1:buttons.length-1))%buttons.length];next.focus();next.click()}})});
let downloadController;const downloadButton=document.querySelector('#download-button'),cancel=document.querySelector('#cancel-download'),status=document.querySelector('#download-status');
downloadButton.addEventListener('click',async()=>{downloadButton.disabled=true;cancel.hidden=false;downloadController=new AbortController();try{const parts=[];for(let i=0;i<4;i++){status.textContent=`Загрузка приложения… ${i*25}%`;const r=await fetch(`downloads/attention-${i}.bin`,{signal:downloadController.signal});if(!r.ok)throw Error('Не удалось скачать файл. Попробуйте ещё раз.');parts.push(await r.arrayBuffer())}status.textContent='Проверяем целостность файла…';const blob=new Blob(parts,{type:'application/vnd.android.package-archive'});if(blob.size!==64640356)throw Error('Файл загружен не полностью. Повторите загрузку.');const digest=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer());const hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');if(hash!=='1738632caab641bb1f145e5e9be69e02073487f0d820e10d107f87dffc01f6be')throw Error('Проверка файла не пройдена. Повторите загрузку.');if(downloadController.signal.aborted)throw new DOMException('Cancelled','AbortError');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Attention-1.6.0.apk';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='Файл проверен и передан браузеру для сохранения.'}catch(e){status.textContent=e.name==='AbortError'?'Загрузка отменена.':e.message}finally{downloadButton.disabled=false;cancel.hidden=true}});cancel.addEventListener('click',()=>downloadController?.abort());

// Calm motion runs only while the phone is visible; the visitor can pause it.
const heroVisual=document.querySelector('.hero-visual'),motionToggle=document.querySelector('.motion-toggle');
let motionPaused=false,heroVisible=true;
function updateMotion(){heroVisual.classList.toggle('motion-paused',motionPaused||!heroVisible||document.hidden)}
motionToggle.addEventListener('click',()=>{motionPaused=!motionPaused;motionToggle.setAttribute('aria-pressed',String(motionPaused));motionToggle.textContent=motionPaused?'Продолжить анимацию':'Остановить анимацию';updateMotion()});
if('IntersectionObserver' in window)new IntersectionObserver(entries=>{heroVisible=entries[0].isIntersecting;updateMotion()},{threshold:0}).observe(heroVisual);
document.addEventListener('visibilitychange',updateMotion);
